import { render, dynamic } from '@solidjs/web';
import { createSignal, For } from 'solid-js';

const products = [
  { id: 1, name: 'Mug', price: 12 },
  { id: 2, name: 'Notebook', price: 8 },
  { id: 3, name: 'Pen', price: 3 },
];

function Card(props) {
  return (
    <article style={{ border: '1px solid #ccc', padding: '0.5rem', margin: '0.5rem 0' }}>
      <h3>{props.product.name}</h3>
      <p>${props.product.price}</p>
    </article>
  );
}

function Row(props) {
  return (
    <p>
      {props.product.name} · ${props.product.price}
    </p>
  );
}

function Tag(props) {
  return <strong style={{ 'margin-right': '1rem' }}>{props.product.name}</strong>;
}

const views = { card: Card, row: Row, tag: Tag };

function App() {
  const [view, setView] = createSignal('card');

  return (
    <>
      <select onChange={(event) => setView(event.currentTarget.value)}>
        <option value="card">Cards</option>
        <option value="row">Rows</option>
        <option value="tag">Tags</option>
      </select>
      <For each={products}>{(product) => <Card product={product} />}</For>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

import { render, dynamic } from '@solidjs/web';
import { createSignal, For } from 'solid-js';

const products = [
  { id: 1, name: 'Mug', price: 12 },
  { id: 2, name: 'Notebook', price: 8 },
  { id: 3, name: 'Pen', price: 3 },
];

function Card(props) {
  return (
    <article style={{ border: '1px solid #ccc', padding: '0.5rem', margin: '0.5rem 0' }}>
      <h3>{props.product.name}</h3>
      <p>${props.product.price}</p>
    </article>
  );
}

function Row(props) {
  return (
    <p>
      {props.product.name} · ${props.product.price}
    </p>
  );
}

function Tag(props) {
  return <strong style={{ 'margin-right': '1rem' }}>{props.product.name}</strong>;
}

const views = { card: Card, row: Row, tag: Tag };

function App() {
  const [view, setView] = createSignal('card');
